unsigned long mmio_addr = 0xFEEDCAFEBEEF;
char write_buffer[8] = {0x10, 0x20, 0x30, 0x40, 0, 0, 0, 0};
size_t length = 4;
long ret_status;

// Function must be used on Linux Systemz platforms.
// Ensures address is valid and does not cross pages.
ret_status = s390_pci_mmio_write(
    mmio_addr + 0x40,
    write_buffer,
    length
);

// Returns 0 on success, or negative errno on failure.
